 94 test("unknown pricing, missing usage, pending and corrupt records never become free requests", () => {
 95   const storageDir = directory();
 96   const ledger = new UsageLedger({ storageDir });
 97   const owner = ledger.owner("source");
 98   const unpriced = ledger.begin(owner, { provider: "custom", model: "gpt-4o" });
 99   ledger.settle(unpriced, usage);
100   ledger.finish(unpriced, "completed");
101   ledger.begin(owner, identity);
102   const summary = ledger.summary();
103   expect(summary.unknownCostRequests).toBe(2);
104   expect(summary.unknownUsageRequests).toBe(1);
105   expect(summary.knownEstimatedCostUsd).toBe(0);
106   const folder = join(storageDir, readdirSync(storageDir)[0]!);
107   writeFileSync(join(folder, `${"a".repeat(64)}.json`), "broken");
108   const restarted = new UsageLedger({ storageDir });
109   expect(restarted.summary({ scope: "store" }).partial).toBe(true);
110   expect(restarted.summary({ scope: "store" }).unknownUsageRequests).toBe(1);
111   expect(restarted.summary({ scope: "store", limit: 1 }).nextCursor).toBeDefined();
